import { initTRPC } from "@trpc/server";

/**
 * Initialization of tRPC backend
 * Should be done only once per backend!
 */
const t = initTRPC.create();

/**
 * Export reusable router and procedure helpers
 * that can be used throughout the router
 */
export const createTRPCRouter = t.router;
export const createCallerFactory = t.createCallerFactory;
export const baseProcedure = t.procedure;

import { z } from "zod";
import { createTRPCRouter, baseProcedure } from "../trpc";

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

export const appRouter = createTRPCRouter({
  chat: baseProcedure
    .input(z.string())
    .query(async function* ({ input }): AsyncGenerator<string, void, void> {
      // Stream the input string character by character with a 50ms delay
      for (const char of input) {
        await sleep(50);
        yield char;
      }
    }),
});

export type AppRouter = typeof appRouter;

import { fetchRequestHandler } from "@trpc/server/adapters/fetch";
import { appRouter } from "@/server/routers/app";

/**
 * tRPC API route handler for Next.js App Router.
 * Catches all HTTP methods (GET, POST, etc.) and routes them through tRPC.
 */
const handler = (req: Request) =>
  fetchRequestHandler({
    endpoint: "/api/trpc",
    req,
    router: appRouter,
    createContext: () => ({}),
  });

export { handler as GET, handler as POST };

