"use client";

import { useEffect, useState } from "react";
import { trpc } from "./TRPCProvider";

export function Chat() {
  const [input, setInput] = useState("");
  const [submittedMessage, setSubmittedMessage] = useState<string | null>(null);
  const [streamedResponse, setStreamedResponse] = useState("");

  // useQuery with `enabled: false` so it doesn't REDACTED-fetch.
  // When `submittedMessage` changes we trigger a new query, and the
  // returned `data` is an AsyncIterable<string> (the streaming response).
  const { data, isLoading, error, isFetching } =
    trpc.chat.useQuery(submittedMessage ?? "", {
      enabled: submittedMessage !== null,
      retry: false,
    });

  // As soon as we receive the AsyncIterable, iterate it and accumulate
  // the streamed characters into the response display.
  useEffect(() => {
    if (!data) {
      setStreamedResponse("");
      return;
    }

    // `coerceAsyncIterableToArray` makes `data` look like a string array,
    // but at runtime it is still an AsyncIterable returned from the
    // streaming link, so we manually iterate it with `for await...of`.
    const iterable = data as unknown as AsyncIterable<string>;
    let cancelled = false;
    let accumulated = "";

    (async () => {
      try {
        for await (const chunk of iterable) {
          if (cancelled) return;
          accumulated += chunk;
          setStreamedResponse(accumulated);
        }
      } catch (err) {
        if (!cancelled) {
          console.error("Stream error", err);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [data]);

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const trimmed = input.trim();
    if (!trimmed) return;
    setStreamedResponse("");
    setSubmittedMessage(trimmed);
  }

  return (
    <div className="flex w-full max-w-2xl flex-col gap-4">
      <form onSubmit={handleSubmit} className="flex gap-2">
        <input
          id="chat-input"
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Type a message..."
          className="flex-1 rounded-md border border-zinc-300 bg-white px-3 py-2 text-sm text-zinc-900 outline-none focus:border-zinc-500 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-100"
          disabled={isFetching}
        />
        <button
          id="chat-submit"
          type="submit"
          className="rounded-md bg-zinc-900 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-zinc-700 disabled:opacity-50 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-300"
          disabled={isFetching || input.trim().length === 0}
        >
          Send
        </button>
      </form>

      <div
        id="chat-response"
        className="min-h-[6rem] rounded-md border border-zinc-200 bg-zinc-50 p-4 font-mono text-sm whitespace-pre-wrap text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100"
      >
        {isLoading && streamedResponse.length === 0
          ? "Connecting..."
          : error
            ? `Error: ${error.message}`
            : streamedResponse || (
                <span className="text-zinc-400">
                  The streamed response will appear here.
                </span>
              )}
      </div>
    </div>
  );
}

