import { createTRPCClient, httpBatchStreamLink } from "@trpc/client";

const client = createTRPCClient({
  links: [
    httpBatchStreamLink({
      url: "http://localhost:3000/api/trpc",
    }),
  ],
});

async function test() {
  console.log("Test 1: short message 'hello'");
  let iter = await client.chat.query("hello");
  let result = "";
  for await (const chunk of iter) {
    result += chunk;
  }
  console.log("Final result:", JSON.stringify(result));
  console.assert(result === "hello", "Test 1 failed");

  console.log("\nTest 2: longer message 'streaming chat with tRPC v11!'");
  iter = await client.chat.query("streaming chat with tRPC v11!");
  result = "";
  for await (const chunk of iter) {
    result += chunk;
  }
  console.log("Final result:", JSON.stringify(result));
  console.assert(result === "streaming chat with tRPC v11!", "Test 2 failed");

  console.log("\nTest 3: empty string");
  iter = await client.chat.query("");
  result = "";
  for await (const chunk of iter) {
    result += chunk;
  }
  console.log("Final result:", JSON.stringify(result));
  console.assert(result === "", "Test 3 failed");

  console.log("\nAll tests passed!");
}

test().catch((err) => {
  console.error("Error:", err);
  process.exit(1);
});
